1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>My Links — prototype 1</title>
7	<style>
8	  :root { --line:#e3e3e6; --muted:#6b7280; --accent:#2563eb; --bg:#f7f7f8; }
9	  * { box-sizing: border-box; }
10	  body { margin:0; font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
11	         color:#111827; background:var(--bg); }
12	  header { padding:22px 28px; border-bottom:1px solid var(--line); background:#fff; }
13	  h1 { font-size:19px; margin:0; }
14	  .sub { color:var(--muted); font-size:13px; margin-top:3px; }
15	  main { max-width:760px; margin:0 auto; padding:24px 20px 60px; }
16	
17	  .adder { display:flex; gap:8px; margin-bottom:8px; }
18	  .adder input { flex:1; padding:11px 13px; border:1px solid var(--line); border-radius:8px;
19	                 font-size:14px; background:#fff; }
20	  .adder button { padding:11px 18px; border:0; border-radius:8px; background:var(--accent);
21	                  color:#fff; font-size:14px; font-weight:600; cursor:pointer; }
22	  .adder button:disabled { opacity:.5; cursor:default; }
23	  .hint { color:var(--muted); font-size:12px; margin:0 0 22px 2px; }
24	
25	  .count { color:var(--muted); font-size:12px; text-transform:uppercase;
26	           letter-spacing:.05em; margin:20px 2px 10px; }
27	
28	  ul { list-style:none; margin:0; padding:0; }
29	  li.card { background:#fff; border:1px solid var(--line); border-radius:10px;
30	            padding:14px 16px; margin-bottom:10px; }
31	  li.card.fresh { animation: pop .5s ease; border-color:#c7d2fe; }
32	  @keyframes pop { from { transform: translateY(-6px); opacity:0 } to { transform:none; opacity:1 } }
33	  .title { font-size:15px; font-weight:600; margin:0; }
34	  .desc { color:#374151; font-size:13px; margin:5px 0 0; line-height:1.45; }
35	  .url { color:var(--muted); font-size:12px; margin-top:7px; display:flex; align-items:center; gap:6px; }
36	  .fav { width:14px; height:14px; border-radius:3px; background:#dbe3ff; display:inline-block;
37	         font-size:9px; text-align:center; line-height:14px; color:#3552b5; font-weight:700; }
38	  .loading { color:var(--muted); font-style:italic; font-size:13px; }
39	</style>
40	</head>
41	<body>
42	<header>
43	  <h1>My Links</h1>
44	  <div class="sub">Your personal library of saved links</div>
45	</header>
46	
47	<main>
48	  <div class="adder">
49	    <input id="url" type="text" placeholder="Paste a link here…" autocomplete="off">
50	    <button id="save" disabled>Save</button>
51	  </div>
52	  <p class="hint">Paste any web address and press Save (or hit Enter).</p>
53	
54	  <div class="count" id="count"></div>
55	  <ul id="list"></ul>
56	</main>
57	
58	<script>
59	// --- prototype-only: simulate fetching a page's title + description ---
60	const KNOWN = {
61	  "stripe.com/blog/payment-api": {
62	    t: "Designing the Stripe Payments API",
63	    d: "How we think about API ergonomics, idempotency, and versioning at scale." },
64	  "nytimes.com/2026/travel/kyoto": {
65	    t: "36 Hours in Kyoto",
66	    d: "Temples at dawn, a tofu lunch, and where to find the quiet streets." },
67	  "wikipedia.org/wiki/Sourdough": {
68	    t: "Sourdough — Wikipedia",
69	    d: "Bread made by the fermentation of dough using naturally occurring lactobacilli and yeast." },
70	};
71	function fakeFetch(raw) {
72	  const key = raw.replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/$/,'');
73	  if (KNOWN[key]) return Promise.resolve(KNOWN[key]);
74	  // fallback: derive something plausible from the URL
75	  const host = (key.split('/')[0]||'link').replace(/\.[a-z]+$/,'');
76	  const slug = (key.split('/').slice(1).join(' ').replace(/[-_]/g,' ')||'Saved page').trim();
77	  const t = (slug.charAt(0).toUpperCase()+slug.slice(1)).slice(0,70) || (host+' page');
78	  return Promise.resolve({ t, d: "A page saved from " + host + "." });
79	}
80	
81	const seed = [
82	  { url:"https://wikipedia.org/wiki/Sourdough", ...KNOWN["wikipedia.org/wiki/Sourdough"] },
83	  { url:"https://nytimes.com/2026/travel/kyoto", ...KNOWN["nytimes.com/2026/travel/kyoto"] },
84	];
85	let items = seed.map(s => ({ url:s.url, title:s.t, desc:s.d }));
86	
87	const list = document.getElementById('list');
88	const input = document.getElementById('url');
89	const btn = document.getElementById('save');
90	const count = document.getElementById('count');
91	
92	function host(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch { return u; } }
93	function render(freshUrl){
94	  count.textContent = items.length + (items.length===1?" link":" links");
95	  list.innerHTML = items.map(it => `
96	    <li class="card ${it.url===freshUrl?'fresh':''}">
97	      <p class="title">${it.title}</p>
98	      <p class="desc">${it.desc}</p>
99	      <div class="url"><span class="fav">${host(it.url)[0]?.toUpperCase()||'•'}</span>${host(it.url)}</div>
100	    </li>`).join('');
101	}
102	input.addEventListener('input', ()=> btn.disabled = input.value.trim().length < 4);
103	function save(){
104	  const url = input.value.trim(); if(url.length<4) return;
105	  input.value=''; btn.disabled=true;
106	  // show a placeholder row while "fetching"
107	  items.unshift({ url, title:"…", desc:"", _loading:true });
108	  renderLoading(url);
109	  fakeFetch(url).then(meta=>{
110	    items[0] = { url, title:meta.t, desc:meta.d };
111	    render(url);
112	  });
113	}
114	function renderLoading(url){
115	  count.textContent = items.length + (items.length===1?" link":" links");
116	  list.innerHTML = items.map(it => it._loading ? `
117	    <li class="card fresh"><p class="loading">Reading the page to get its name…</p>
118	      <div class="url">${host(it.url)}</div></li>` : `
119	    <li class="card">
120	      <p class="title">${it.title}</p><p class="desc">${it.desc}</p>
121	      <div class="url"><span class="fav">${host(it.url)[0]?.toUpperCase()||'•'}</span>${host(it.url)}</div>
122	    </li>`).join('');
123	}
124	btn.addEventListener('click', save);
125	input.addEventListener('keydown', e=>{ if(e.key==='Enter') save(); });
126	render();
127	</script>
128	</body>
129	</html>
