1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>My Links — prototype 2</title>
7	<style>
8	  :root { --line:#e3e3e6; --muted:#6b7280; --accent:#2563eb; --bg:#f7f7f8; --warn:#b45309; }
9	  * { box-sizing: border-box; }
10	  body { margin:0; font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
11	         color:#111827; background:var(--bg); }
12	  header { padding:22px 28px; border-bottom:1px solid var(--line); background:#fff; }
13	  h1 { font-size:19px; margin:0; }
14	  .sub { color:var(--muted); font-size:13px; margin-top:3px; }
15	  main { max-width:760px; margin:0 auto; padding:24px 20px 60px; }
16	
17	  .adder { display:flex; gap:8px; margin-bottom:8px; }
18	  .adder input { flex:1; padding:11px 13px; border:1px solid var(--line); border-radius:8px;
19	                 font-size:14px; background:#fff; }
20	  .adder button { padding:11px 18px; border:0; border-radius:8px; background:var(--accent);
21	                  color:#fff; font-size:14px; font-weight:600; cursor:pointer; }
22	  .adder button:disabled { opacity:.5; cursor:default; }
23	  .hint { color:var(--muted); font-size:12px; margin:0 0 10px 2px; }
24	
25	  .flash { background:#fffbeb; border:1px solid #fde68a; color:var(--warn); font-size:13px;
26	           border-radius:8px; padding:10px 13px; margin:0 0 16px; display:none; }
27	  .flash.show { display:block; }
28	
29	  .count { color:var(--muted); font-size:12px; text-transform:uppercase;
30	           letter-spacing:.05em; margin:12px 2px 10px; }
31	
32	  ul { list-style:none; margin:0; padding:0; }
33	  li.card { background:#fff; border:1px solid var(--line); border-radius:10px;
34	            padding:14px 16px; margin-bottom:10px; cursor:pointer; transition:box-shadow .15s, border-color .15s; }
35	  li.card:hover { box-shadow:0 2px 10px rgba(0,0,0,.07); border-color:#c7d2fe; }
36	  li.card.fresh { animation: pop .5s ease; }
37	  li.card.pulse { animation: pulse 1.2s ease; }
38	  @keyframes pop { from { transform: translateY(-6px); opacity:0 } to { transform:none; opacity:1 } }
39	  @keyframes pulse { 0%,100%{ box-shadow:0 0 0 0 rgba(37,99,235,0) } 30%{ box-shadow:0 0 0 4px rgba(37,99,235,.25); border-color:var(--accent) } }
40	  .title { font-size:15px; font-weight:600; margin:0; color:#111827; }
41	  .title .ext { color:var(--muted); font-size:12px; font-weight:400; margin-left:6px; }
42	  .desc { color:#374151; font-size:13px; margin:5px 0 0; line-height:1.45; }
43	  .desc.faded { color:var(--muted); font-style:italic; }
44	  .url { color:var(--muted); font-size:12px; margin-top:7px; display:flex; align-items:center; gap:6px; }
45	  .fav { width:14px; height:14px; border-radius:3px; background:#dbe3ff; display:inline-block;
46	         font-size:9px; text-align:center; line-height:14px; color:#3552b5; font-weight:700; }
47	  .loading { color:var(--muted); font-style:italic; font-size:13px; }
48	</style>
49	</head>
50	<body>
51	<header>
52	  <h1>My Links</h1>
53	  <div class="sub">Your personal library of saved links</div>
54	</header>
55	
56	<main>
57	  <div class="adder">
58	    <input id="url" type="text" placeholder="Paste a link here…" autocomplete="off">
59	    <button id="save" disabled>Save</button>
60	  </div>
61	  <p class="hint">Click any saved link to open the real page in a new tab.</p>
62	
63	  <div class="flash" id="flash"></div>
64	  <div class="count" id="count"></div>
65	  <ul id="list"></ul>
66	</main>
67	
68	<script>
69	const KNOWN = {
70	  "stripe.com/blog/payment-api": { t:"Designing the Stripe Payments API",
71	    d:"How we think about API ergonomics, idempotency, and versioning at scale." },
72	  "nytimes.com/2026/travel/kyoto": { t:"36 Hours in Kyoto",
73	    d:"Temples at dawn, a tofu lunch, and where to find the quiet streets." },
74	  "wikipedia.org/wiki/Sourdough": { t:"Sourdough — Wikipedia",
75	    d:"Bread made by fermentation of dough using naturally occurring lactobacilli and yeast." },
76	};
77	function normalize(raw){ return raw.trim().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/$/,'').toLowerCase(); }
78	function fakeFetch(raw){
79	  const key = normalize(raw);
80	  // simulate an unreadable page
81	  if (key.includes("cant-read") || key.includes("noname")) return Promise.resolve({ fail:true });
82	  if (KNOWN[key]) return Promise.resolve(KNOWN[key]);
83	  const host = (key.split('/')[0]||'link').replace(/\.[a-z]+$/,'');
84	  const slug = (key.split('/').slice(1).join(' ').replace(/[-_]/g,' ')||'').trim();
85	  const t = slug ? (slug.charAt(0).toUpperCase()+slug.slice(1)).slice(0,70) : host+" page";
86	  return Promise.resolve({ t, d:"A page saved from "+host+"." });
87	}
88	
89	let items = [
90	  { url:"https://wikipedia.org/wiki/Sourdough", title:KNOWN["wikipedia.org/wiki/Sourdough"].t, desc:KNOWN["wikipedia.org/wiki/Sourdough"].d },
91	  { url:"https://nytimes.com/2026/travel/kyoto", title:KNOWN["nytimes.com/2026/travel/kyoto"].t, desc:KNOWN["nytimes.com/2026/travel/kyoto"].d },
92	];
93	
94	const list=document.getElementById('list'), input=document.getElementById('url'),
95	      btn=document.getElementById('save'), count=document.getElementById('count'), flash=document.getElementById('flash');
96	
97	function host(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch { return u; } }
98	function fullUrl(u){ return /^https?:\/\//.test(u) ? u : "https://"+u; }
99	function showFlash(msg){ flash.textContent=msg; flash.classList.add('show'); }
100	function hideFlash(){ flash.classList.remove('show'); }
101	
102	function cardHtml(it,i,cls=''){
103	  if(it._loading) return `<li class="card fresh"><p class="loading">Reading the page to get its name…</p>
104	     <div class="url">${host(it.url)}</div></li>`;
105	  const title = it.failed
106	    ? `${host(it.url)}<span class="ext">· couldn't read the page name</span>`
107	    : `${it.title}<span class="ext">↗ open</span>`;
108	  const desc = it.failed
109	    ? `<p class="desc faded">We couldn't read this page's name. It's saved and will still open — you can rename it later.</p>`
110	    : `<p class="desc">${it.desc}</p>`;
111	  return `<li class="card ${cls}" data-i="${i}">
112	     <p class="title">${title}</p>${desc}
113	     <div class="url"><span class="fav">${host(it.url)[0]?.toUpperCase()||'•'}</span>${host(it.url)}</div></li>`;
114	}
115	function render(freshUrl, pulseIdx){
116	  count.textContent = items.length + (items.length===1?" link":" links");
117	  list.innerHTML = items.map((it,i)=> cardHtml(it,i, it.url===freshUrl?'fresh':(i===pulseIdx?'pulse':''))).join('');
118	  [...list.querySelectorAll('.card[data-i]')].forEach(el=>{
119	    el.addEventListener('click', ()=>{ const it=items[+el.dataset.i]; window.open(fullUrl(it.url),'_blank'); });
120	  });
121	}
122	
123	input.addEventListener('input', ()=> btn.disabled = input.value.trim().length<4);
124	function save(){
125	  const url=input.value.trim(); if(url.length<4) return;
126	  const dupIdx = items.findIndex(it=> normalize(it.url)===normalize(url));
127	  if(dupIdx>-1){
128	    input.value=''; btn.disabled=true;
129	    showFlash("You already saved this one — here it is. (No duplicate was made.)");
130	    render(null, dupIdx);
131	    document.querySelectorAll('.card')[dupIdx]?.scrollIntoView({behavior:'smooth',block:'center'});
132	    return;
133	  }
134	  hideFlash(); input.value=''; btn.disabled=true;
135	  items.unshift({ url, _loading:true });
136	  render();
137	  fakeFetch(url).then(meta=>{
138	    items[0] = meta.fail ? { url, failed:true } : { url, title:meta.t, desc:meta.d };
139	    render(url);
140	  });
141	}
142	btn.addEventListener('click', save);
143	input.addEventListener('keydown', e=>{ if(e.key==='Enter') save(); });
144	render();
145	</script>
146	</body>
147	</html>
