1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>My Links — prototype 3 (editing styles)</title>
7	<style>
8	  :root { --line:#e3e3e6; --muted:#6b7280; --accent:#2563eb; --bg:#f7f7f8; }
9	  * { box-sizing:border-box; }
10	  body { margin:0; font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif; color:#111827; background:var(--bg); }
11	  header { padding:22px 28px; border-bottom:1px solid var(--line); background:#fff; }
12	  h1 { font-size:19px; margin:0; }
13	  .sub { color:var(--muted); font-size:13px; margin-top:3px; }
14	  main { max-width:760px; margin:0 auto; padding:20px 20px 60px; }
15	
16	  /* prototype-only comparison control */
17	  .switch { background:#111827; color:#fff; border-radius:10px; padding:12px 14px; margin-bottom:22px; }
18	  .switch .lbl { font-size:11px; text-transform:uppercase; letter-spacing:.06em; opacity:.7; margin-bottom:8px; }
19	  .switch button { background:#374151; color:#d1d5db; border:0; border-radius:7px; padding:8px 12px;
20	                   font-size:13px; cursor:pointer; margin-right:6px; }
21	  .switch button.on { background:var(--accent); color:#fff; font-weight:600; }
22	  .switch .desc { font-size:12px; opacity:.85; margin-top:9px; }
23	
24	  ul { list-style:none; margin:0; padding:0; }
25	  li.card { background:#fff; border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:10px;
26	            cursor:pointer; position:relative; }
27	  li.card.editing { cursor:default; border-color:#c7d2fe; }
28	  li.card:hover .editbtn { opacity:1; }
29	  .editbtn { position:absolute; top:12px; right:12px; background:#f3f4f6; border:1px solid var(--line);
30	             border-radius:7px; font-size:12px; padding:4px 9px; cursor:pointer; opacity:0; transition:opacity .12s; }
31	  .title { font-size:15px; font-weight:600; margin:0; padding-right:60px; }
32	  .title .ext { color:var(--muted); font-size:12px; font-weight:400; margin-left:6px; }
33	  .desc { color:#374151; font-size:13px; margin:5px 0 0; line-height:1.45; }
34	  .desc.faded { color:var(--muted); font-style:italic; }
35	  .url { color:var(--muted); font-size:12px; margin-top:7px; display:flex; align-items:center; gap:6px; }
36	  .fav { width:14px; height:14px; border-radius:3px; background:#dbe3ff; display:inline-block; font-size:9px;
37	         text-align:center; line-height:14px; color:#3552b5; font-weight:700; }
38	
39	  /* editing fields */
40	  label.f { display:block; font-size:11px; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:10px 0 3px; }
41	  input.f, textarea.f { width:100%; border:1px solid #c7d2fe; border-radius:7px; padding:8px 10px; font-size:14px;
42	                        font-family:inherit; background:#fff; }
43	  textarea.f { resize:vertical; min-height:52px; }
44	  .row { display:flex; gap:8px; margin-top:12px; }
45	  .row button { border:0; border-radius:7px; padding:8px 15px; font-size:13px; font-weight:600; cursor:pointer; }
46	  .save { background:var(--accent); color:#fff; }
47	  .cancel { background:#f3f4f6; color:#374151; }
48	
49	  /* per-field inline (style C) */
50	  .fieldedit { display:flex; gap:6px; align-items:flex-start; }
51	  .fieldedit input, .fieldedit textarea { flex:1; }
52	  .pen { color:var(--accent); font-size:12px; cursor:pointer; margin-left:6px; opacity:0; }
53	  li.card:hover .pen { opacity:.7; }
54	  .ok { background:var(--accent); color:#fff; border:0; border-radius:6px; padding:6px 10px; cursor:pointer; font-size:12px; }
55	
56	  /* dialog (style B) */
57	  .backdrop { position:fixed; inset:0; background:rgba(17,24,39,.45); display:none; align-items:center; justify-content:center; }
58	  .backdrop.show { display:flex; }
59	  .dialog { background:#fff; border-radius:12px; padding:20px 22px; width:440px; max-width:92vw; box-shadow:0 20px 50px rgba(0,0,0,.3); }
60	  .dialog h3 { margin:0 0 4px; font-size:16px; }
61	  .dialog .did { color:var(--muted); font-size:12px; margin-bottom:6px; }
62	</style>
63	</head>
64	<body>
65	<header>
66	  <h1>My Links</h1>
67	  <div class="sub">Your personal library of saved links</div>
68	</header>
69	
70	<main>
71	  <div class="switch">
72	    <div class="lbl">Prototype control · try editing three ways</div>
73	    <button data-m="A" class="on">A · Edit in place</button>
74	    <button data-m="B">B · Edit in a pop-up</button>
75	    <button data-m="C">C · Edit each field</button>
76	    <div class="desc" id="modeDesc"></div>
77	  </div>
78	
79	  <ul id="list"></ul>
80	</main>
81	
82	<div class="backdrop" id="backdrop"><div class="dialog" id="dialog"></div></div>
83	
84	<script>
85	let mode='A';
86	let items=[
87	  { url:"https://nytimes.com/2026/travel/kyoto", title:"36 Hours in Kyoto",
88	    desc:"Temples at dawn, a tofu lunch, and where to find the quiet streets." },
89	  { url:"https://medium.com/@dev/p/9f3a2b-untitled-draft-copy-2",
90	    title:"9f3a2b untitled draft copy 2", desc:"A page saved from medium." },
91	  { url:"https://cant-read.example.com/page", failed:true },
92	];
93	const MODES={
94	  A:"Hover a link, click Edit, and the card turns into a little form right where it sits.",
95	  B:"Hover a link, click Edit, and a focused pop-up opens with the fields; the library dims behind it.",
96	  C:"Hover a link and a small pencil appears next to each piece of text — click to fix just that one thing."
97	};
98	
99	const list=document.getElementById('list'), backdrop=document.getElementById('backdrop'),
100	      dialog=document.getElementById('dialog'), modeDesc=document.getElementById('modeDesc');
101	let editing=null; // {i} for A, {i,field} for C
102	
103	function host(u){ try{ return new URL(u).hostname.replace(/^www\./,''); }catch{ return u; } }
104	function full(u){ return /^https?:\/\//.test(u)?u:"https://"+u; }
105	function esc(s){ return (s||'').replace(/</g,'&lt;'); }
106	
107	function view(it,i){
108	  const title = it.failed
109	    ? `${host(it.url)}<span class="ext">· name couldn't be read</span>`
110	    : `${esc(it.title)}<span class="ext">↗ open</span>`;
111	  const desc = it.failed
112	    ? `<p class="desc faded">We couldn't read this page's name. It's saved and will still open — rename it below.</p>`
113	    : `<p class="desc">${esc(it.desc)}</p>`;
114	  if(mode==='C'){
115	    return `<li class="card editing" data-i="${i}">
116	      <div class="title">${fieldC(it,i,'title',title)}</div>
117	      <div>${fieldC(it,i,'desc',desc)}</div>
