62	  { url:"https://wikipedia.org/wiki/Sourdough", title:"Sourdough — Wikipedia", desc:"Bread by fermentation of dough.", note:"24h cold-proof for extra tang.", tags:["recipes","baking"] },
63	  { url:"https://seriouseats.com/pizza-dough", title:"The Best Pizza Dough", desc:"A cold-ferment dough for blistered crust.", note:"", tags:["recipes","baking"] },
64	  { url:"https://cooking.com/weeknight-ramen", title:"Weeknight Ramen", desc:"A fast broth for busy evenings.", note:"", tags:["recipes"] },
65	  { url:"https://nytimes.com/2026/travel/kyoto", title:"36 Hours in Kyoto", desc:"Temples at dawn and quiet streets.", note:"Book a ryokan early — they fill up.", tags:["travel"] },
66	  { url:"https://atlasobscura.com/lisbon", title:"Hidden Lisbon", desc:"Miradouros, trams, and pastel de nata.", note:"", tags:["travel"] },
67	  { url:"https://stripe.com/blog/payment-api", title:"Designing the Stripe Payments API", desc:"Idempotency and versioning at scale.", note:"", tags:["work","dev"] },
68	  { url:"https://linear.app/method", title:"The Linear Method", desc:"How a focused team ships software.", note:"", tags:["work"] },
69	  { url:"https://reactjs.org/hooks", title:"Thinking in Hooks", desc:"State and effects without classes.", note:"", tags:["dev"] },
70	];
71	function tagCounts(){ const m={}; items.forEach(i=>i.tags.forEach(t=>m[t]=(m[t]||0)+1)); return m; }
72	
73	const qEl=document.getElementById('q'), clearq=document.getElementById('clearq'),
74	      bar=document.getElementById('bar'), count=document.getElementById('count'), list=document.getElementById('list');
75	function host(u){ try{ return new URL(u).hostname.replace(/^www\./,''); }catch{ return u; } }
76	function full(u){ return /^https?:\/\//.test(u)?u:"https://"+u; }
77	function esc(s){ return (s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
78	function hl(s){ s=esc(s); if(!q) return s;
79	  const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
80	  return s.replace(re,'<mark>$1</mark>'); }
81	
82	function inField(it){ const n=q.toLowerCase();
83	  return { title:it.title.toLowerCase().includes(n), desc:(it.desc||'').toLowerCase().includes(n),
84	           note:(it.note||'').toLowerCase().includes(n), url:it.url.toLowerCase().includes(n) }; }
85	function hits(it){ const f=inField(it); return f.title||f.desc||f.note||f.url; }
86	function whereText(it){ const f=inField(it); const w=[];
87	  if(f.note) w.push('your note'); if(f.url) w.push('the web address');
88	  // only surface the non-obvious places (note/address); title/desc are visible with highlight
89	  return w.length? 'Found in '+w.join(' & ') : ''; }
90	
91	function renderBar(){
92	  const c=tagCounts();
93	  bar.innerHTML=Object.keys(c).sort().map(t=>`<span class="t ${selected.includes(t)?'on':''}" data-topic="${t}">${t}<span class="c">${c[t]}</span></span>`).join('');
94	  bar.querySelectorAll('[data-topic]').forEach(el=>el.addEventListener('click',()=>{
95	    const t=el.dataset.topic; selected.includes(t)? selected=selected.filter(x=>x!==t): selected.push(t); render(); }));
96	}
97	function render(){
98	  let shown=items.filter(it=> selected.every(t=>it.tags.includes(t)));
99	  if(q) shown=shown.filter(hits);
100	  const label = q ? `${shown.length} match ${JSON.stringify(q)}` : (selected.length? `${shown.length} shown` : `${items.length} links`);
101	  count.textContent=label;
102	  clearq.classList.toggle('show', !!q);
103	  if(!shown.length){
104	    list.innerHTML=`<div class="empty">No links ${q?`match “${esc(q)}”`:''}${q&&selected.length?' in ':''}${selected.length?`your selected topics`:''}.<br>Try a different word${selected.length?', or clear a topic':''}.</div>`;
105	    return;
106	  }
107	  list.innerHTML=shown.map(it=>{ const i=items.indexOf(it); const w=q?whereText(it):'';
108	    return `<li class="card" data-open="${i}">
109	      <p class="title">${hl(it.title)}<span class="ext">↗ open</span></p>
110	      <p class="desc">${hl(it.desc)}</p>
111	      ${it.note?`<p class="note"><b>Note to self:</b> ${hl(it.note)}</p>`:''}
112	      <div class="url"><span class="fav">${(host(it.url)[0]||'•').toUpperCase()}</span>${hl(host(it.url))}</div>
113	      <div class="tags">${it.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div>
114	      ${w?`<span class="where">${w}</span>`:''}
115	    </li>`; }).join('');
116	  list.querySelectorAll('[data-open]').forEach(el=>el.addEventListener('click',()=>window.open(full(items[+el.dataset.open].url),'_blank')));
117	}
118	qEl.addEventListener('input',()=>{ q=qEl.value.trim(); render(); });
119	clearq.addEventListener('click',()=>{ q=''; qEl.value=''; qEl.focus(); render(); });
120	renderBar(); render();
121	</script>
122	</body>
123	</html>
