61	<script>
62	let q='', selected=[];
63	let items=[
64	  { url:"https://wikipedia.org/wiki/Sourdough", title:"Sourdough — Wikipedia", desc:"Bread by fermentation of dough.", note:"24h cold-proof for extra tang.", tags:["recipes","baking"] },
65	  { url:"https://seriouseats.com/pizza-dough", title:"The Best Pizza Dough", desc:"A cold-ferment dough for blistered crust.", note:"", tags:["recipes","baking"] },
