67	  { url:"https://nytimes.com/2026/travel/kyoto", title:"36 Hours in Kyoto", desc:"Temples at dawn and quiet streets.", note:"Book a ryokan early — they fill up.", tags:["travel"] },
68	  { url:"https://atlasobscura.com/lisbon", title:"Hidden Lisbon", desc:"Miradouros, trams, and pastel de nata.", note:"", tags:["travel"] },
69	  { url:"https://stripe.com/blog/payment-api", title:"Designing the Stripe Payments API", desc:"Idempotency and versioning at scale.", note:"", tags:["work","dev"] },
70	  { url:"https://linear.app/method", title:"The Linear Method", desc:"How a focused team ships software.", note:"", tags:["work"] },
71	  { url:"https://reactjs.org/hooks", title:"Thinking in Hooks", desc:"State and effects without classes.", note:"", tags:["dev"] },
72	];
73	function tagCounts(){ const m={}; items.forEach(i=>i.tags.forEach(t=>m[t]=(m[t]||0)+1)); return m; }
74	
75	const qEl=document.getElementById('q'), clearq=document.getElementById('clearq'),
76	      bar=document.getElementById('bar'), count=document.getElementById('count'), list=document.getElementById('list');
