81	// parse query into terms: quoted phrases stay whole, otherwise split on spaces
82	function terms(){
83	  const out=[]; const re=/"([^"]+)"|(\S+)/g; let m;
84	  while((m=re.exec(q))!==null){ const t=(m[1]||m[2]).toLowerCase().trim(); if(t) out.push(t); }
