88	function matchAll(it){ const T=terms(); if(!T.length) return true;
89	  const f=fields(it); const hay=(f.title+' '+f.desc+' '+f.note+' '+f.url).toLowerCase();
90	  return T.every(t=>hay.includes(t)); }
91	function whereText(it){ const T=terms(); if(!T.length) return '';
92	  const f=fields(it); const inNote=T.some(t=>f.note.toLowerCase().includes(t));
93	  const inUrl=T.some(t=>f.url.toLowerCase().includes(t)); const w=[];
94	  if(inNote) w.push('your note'); if(inUrl) w.push('the web address');
